"use strict";
// The dashboard shell. Shipped; learners do not edit this file. It loads /api/runs, lets you choose a run and
// the run to compare it with, and calls every registered panel with the same context object.
//
// A panel file calls Dashboard.register({id, title, lab, render(ctx, el)}). Inside render:
//   ctx.run, ctx.base            run.json objects (base is the comparison run, or null); each has .id and ._cases
//   ctx.cases, ctx.baseCases     their cases.jsonl lines
//   ctx.runs                     every run, oldest first;  ctx.kept the last kept run id
//   ctx.loadCases(id)            Promise of one run's cases;  ctx.prices the prices table
//   ctx.lib                      helpers (DashLib)
// render may return a Promise. A panel that throws shows its error text in its own box and nothing else breaks.
window.Dashboard = (function () {
  const L = window.DashLib;
  const panels = [];
  const caseCache = new Map();
  const state = { runs: [], kept: null, confirmations: [], runId: null, baseId: null, source: "runs", prices: null };

  function register(panel) { panels.push(panel); }

  function notBuilt(el, label) {
    el.replaceChildren(L.el("p", { class: "not-built" }, "Panel not built yet.",
      label ? L.el("span", { class: "muted" }, " (" + label + ")") : null));
  }

  async function fetchJson(url) {
    const res = await fetch(url);
    if (!res.ok) throw new Error(url + " answered " + res.status);
    return res.json();
  }

  function loadCases(id) {
    if (!id) return Promise.resolve([]);
    if (!caseCache.has(id)) {
      caseCache.set(id, fetchJson("/api/runs/" + encodeURIComponent(id)).then((d) => d.cases || []));
    }
    return caseCache.get(id);
  }

  const byId = (id) => state.runs.find((r) => r.id === id) || null;

  function defaultBase(run) {
    if (!run) return null;
    if (run.parent && byId(run.parent)) return run.parent;
    const i = state.runs.findIndex((r) => r.id === run.id);
    return i > 0 ? state.runs[i - 1].id : null;
  }

  function fillSelect(sel, withNone, value) {
    sel.replaceChildren();
    if (withNone) sel.append(L.el("option", { value: "", text: "no comparison" }));
    for (const r of [...state.runs].reverse()) {
      sel.append(L.el("option", { value: r.id, text: r.id + (r.id === state.kept ? " (kept)" : "") + "  " + L.changeText(r) }));
    }
    sel.value = value || "";
  }

  async function context() {
    const run = byId(state.runId);
    const base = byId(state.baseId);
    const [cases, baseCases] = await Promise.all([loadCases(state.runId), loadCases(state.baseId)]);
    const runObj = run ? Object.assign({}, run, { _cases: cases }) : null;
    const baseObj = base ? Object.assign({}, base, { _cases: baseCases }) : null;
    return { runs: state.runs, kept: state.kept, confirmations: state.confirmations, run: runObj, base: baseObj,
      cases, baseCases, loadCases, prices: state.prices, lib: L, select };
  }

  async function renderAll() {
    const host = document.getElementById("panels");
    host.replaceChildren();
    const toc = document.getElementById("toc");
    toc.replaceChildren();
    const ctx = await context();
    for (const p of panels) {
      const body = L.el("div", { class: "panel-body" });
      host.append(L.el("section", { class: "panel", id: "panel-" + p.id, "aria-labelledby": "h-" + p.id },
        L.el("h2", { id: "h-" + p.id }, p.title, L.el("span", { class: "lab", text: p.lab || "" })), body));
      toc.append(L.el("a", { href: "#panel-" + p.id, text: p.title }));
      try {
        await p.render(ctx, body);
      } catch (err) {
        body.replaceChildren(L.el("div", { class: "panel-error", role: "alert" },
          L.el("strong", { text: "This panel stopped with an error." }), L.el("br"),
          L.el("code", { text: String(err && err.message ? err.message : err) })));
        console.error(p.id, err);
      }
    }
  }

  function select(id) {
    state.runId = id;
    state.baseId = defaultBase(byId(id));
    syncControls();
    renderAll();
  }

  function syncControls() {
    fillSelect(document.getElementById("run-select"), false, state.runId);
    fillSelect(document.getElementById("base-select"), true, state.baseId);
  }

  async function load() {
    const status = document.getElementById("status");
    status.textContent = "Loading runs.";
    caseCache.clear();
    let data = await fetchJson("/api/runs?source=" + state.source);
    if (!data.runs.length && state.source === "runs") {
      const ref = await fetchJson("/api/runs?source=reference");
      if (ref.runs.length) {
        data = ref;
        document.getElementById("use-reference").checked = true;
        status.textContent = "You have no runs yet, so this shows the reference runs.";
      }
    }
    state.runs = data.runs;
    state.kept = data.kept;
    state.confirmations = data.confirmations || [];
    if (!state.runs.length) status.textContent = "No runs yet. Run `python -m harness run --pack <your-pack>` and reload.";
    else if (!status.textContent.startsWith("You have no runs")) status.textContent = state.runs.length + " runs loaded.";
    if (!byId(state.runId)) state.runId = state.kept && byId(state.kept) ? state.kept
      : state.runs.length ? state.runs[state.runs.length - 1].id : null;
    if (!byId(state.baseId)) state.baseId = defaultBase(byId(state.runId));
    syncControls();
    await renderAll();
  }

  async function start() {
    document.getElementById("run-select").addEventListener("change", (e) => select(e.target.value));
    document.getElementById("base-select").addEventListener("change", (e) => { state.baseId = e.target.value || null; renderAll(); });
    document.getElementById("reload").addEventListener("click", () => load().catch(showFatal));
    document.getElementById("use-reference").addEventListener("change", (e) => {
      state.source = e.target.checked ? "reference" : "runs"; state.runId = null; state.baseId = null;
      load().catch(showFatal);
    });
    try { state.prices = await fetchJson("/api/config/prices"); } catch (e) { state.prices = null; }
    load().catch(showFatal);
  }

  function showFatal(err) {
    document.getElementById("status").textContent = "Could not load runs: " + err.message;
  }

  return { register, notBuilt, start, select };
})();
